<script setup lang="ts">
import {ComboboxRoot,ComboboxAnchor,ComboboxInput,ComboboxTrigger,ComboboxCancel,ComboboxPortal,ComboboxContent,ComboboxViewport,ComboboxItem,ComboboxItemIndicator,ComboboxEmpty} from 'reka-ui';
const props=defineProps<{modelValue:string;label:string;options:{value:string;label:string;disabled?:boolean}[];disabled?:boolean}>();const emit=defineEmits<{'update:modelValue':[value:string]}>();const id=useId(),mounted=ref(false),open=ref(false);
onMounted(()=>mounted.value=true);const display=(value:unknown)=>props.options.find(o=>o.value===value)?.label||'';
function choose(value:unknown){const option=props.options.find(o=>o.value===value);if(option&&!option.disabled)emit('update:modelValue',option.value);}
const route=useRoute();watch(()=>route.fullPath,()=>open.value=false);
</script>
<template><div class="control-field"><label :for="id">{{ label }}</label><select v-if="!mounted" :id="id" class="field-input" :value="modelValue" :disabled="disabled" @change="choose(($event.target as HTMLSelectElement).value)"><option v-for="o in options" :key="o.value" :value="o.value" :disabled="o.disabled">{{ o.label }}</option></select><ComboboxRoot v-else v-model:open="open" :model-value="modelValue" :disabled="disabled" @update:model-value="choose"><ComboboxAnchor class="field-combo"><ComboboxInput :id="id" class="field-input" :display-value="display" :placeholder="`Find ${label.toLowerCase()}`" autocomplete="off" @keydown.tab="open=false"/><ComboboxCancel :aria-label="`Clear ${label.toLowerCase()} search`" class="combo-icon">×</ComboboxCancel><ComboboxTrigger :aria-label="`Show ${label.toLowerCase()} choices`" class="combo-icon"><ControlChevron :open="open" /></ComboboxTrigger></ComboboxAnchor><ComboboxPortal><ComboboxContent class="field-popup combo-popup" position="popper" :side-offset="6" :collision-padding="12" @escape-key-down.stop><ComboboxViewport class="field-viewport"><ComboboxEmpty class="field-option">No matching choices. Clear the search to see all choices.</ComboboxEmpty><ComboboxItem v-for="o in options" :key="o.value" :value="o.value" :disabled="o.disabled" class="field-option" :data-option-value="o.value"><ComboboxItemIndicator class="field-check">✓</ComboboxItemIndicator>{{ o.label }}</ComboboxItem></ComboboxViewport></ComboboxContent></ComboboxPortal></ComboboxRoot><small class="field-hint">Type to find a choice. Selection applies only when you choose an option.</small></div></template>
<style scoped>.field-combo{display:flex;align-items:center;min-width:0}.field-combo input{min-width:0;border-radius:7px 0 0 7px}.combo-icon{display:grid;place-items:center;flex:0 0 44px;min-height:44px;padding:0;background:var(--fieldSurface);color:var(--fieldText);border:1px solid var(--fieldBorder);border-left:0;border-radius:0;font-size:19px;box-shadow:none}.combo-icon:last-child{border-radius:0 7px 7px 0}.combo-popup{width:var(--reka-combobox-trigger-width);max-height:min(360px,var(--reka-combobox-content-available-height));overflow-y:auto}</style>
